// Submit every URL in the live sitemap to IndexNow via Bing's endpoint (shared with other IndexNow engines).
// Run AFTER a deploy:  node scripts/indexnow.mjs
// The key file is generated by gen-agent-files.mjs and served at /<key>.txt.
import { SITE } from '../src/config/site.js'

const KEY = 'a1b2c3d4e5f60718293a4b5c6d7e8f90'
const origin = `https://${SITE.domain}`

const xml = await (await fetch(`${origin}/sitemap.xml`)).text()
const urlList = [...xml.matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => m[1])
if (!urlList.length) {
  console.error('No URLs found in the live sitemap — nothing submitted.')
  process.exit(1)
}

const res = await fetch('https://www.bing.com/indexnow', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json; charset=utf-8' },
  body: JSON.stringify({ host: SITE.domain, key: KEY, keyLocation: `${origin}/${KEY}.txt`, urlList }),
})
console.log(`IndexNow: submitted ${urlList.length} URLs — HTTP ${res.status}`)
process.exit(res.ok || res.status === 202 ? 0 : 1)
